create or replace function t011_full_name(
  p_first  in varchar2,
  p_middle in varchar2,
  p_last   in varchar2
) return varchar2 is
  v_parts sys.odci_string_table;
begin
  v_parts := sys.odci_string_table();
  v_parts.EXTEND(3);
  v_parts(1) := p_first;
  v_parts(2) := p_middle;
  v_parts(3) := p_last;

  return trim(
    (SELECT LISTAGG(val, ' ') WITHIN GROUP (ORDER BY LEVEL)
     FROM dual
     CONNECT BY LEVEL <= 3
     WHERE (SELECT val FROM TABLE(v_parts) WHERE COLUMN_VALUE = v_parts(LEVEL)) IS NOT NULL)
  );
end t011_full_name;
/
